(function () {
  function st(){return App.state;}
  function esc(v){return UI.esc(v==null?"":String(v));}
  function all(){return st().tenants||[];}
  function current(){return App.currentTenant();}
  function active(){return all().filter(function(t){return t.status!=="archived";});}
  function statCards(t, members, projects){return '<div class="grid g4">'+UI.stat({label:"成员数",value:String(members),unit:"人",delta:"租户成员关系"})+UI.stat({label:"项目数",value:String(projects),unit:"个",delta:"按 tenant_id 归属"})+UI.stat({label:"周期预算",value:App.formatMoney(t.budget)})+UI.stat({label:"已使用",value:App.formatMoney(t.spent)})+'</div>';}
  function listPage(){
    var ts=active();
    return '<div class="page">'+UI.pageHead({eyebrow:"Enterprise · Tenant spaces",title:"内部租户空间",desc:"单一企业主体统一治理，按事业部、部门、制作中心或业务单元划分隔离空间。租户不是独立法人或外部 SaaS 客户。",actions:App.hasPerm("tenant:manage")?'<button class="btn btn-primary" data-act="create">创建内部租户</button>':""})+
    '<div class="notice info mb-16">'+UI.icon("shield",15)+'<span>企业主体：'+esc(st().workspace.name)+'。租户之间默认隔离；跨租户访问必须授权并审计。</span></div>'+
    '<div class="grid g3">'+ts.map(function(t){var n=st().projects.filter(function(p){return p.tenantId===t.id;}).length,pct=t.budget?Math.round(t.spent/t.budget*100):0;return '<article class="card tenant-card"><div class="card-body"><div class="between"><span class="eyebrow">'+esc(t.code)+'</span>'+UI.statusBadge(t.status)+'</div><h3 class="tenant-name">'+esc(t.name)+'</h3><p class="small muted">'+esc(t.orgUnit)+' · '+esc(t.description)+'</p><div class="tenant-metrics"><div><b>'+t.memberIds.length+'</b><small>成员</small></div><div><b>'+n+'</b><small>项目</small></div><div><b>'+App.formatMoney(t.spent)+'</b><small>已用预算</small></div></div><div class="between tiny muted mt-12"><span>预算使用</span><b>'+pct+'%</b></div>'+UI.progress(pct)+'<div class="row wrap mt-16"><a class="btn btn-sm" href="'+App.link("tenants/detail",{id:t.id})+'">空间详情</a>'+(t.status==="active"&&(App.currentUser.tenantIds||[]).indexOf(t.id)>-1?'<button class="btn btn-sm '+(st().currentTenantId===t.id?"btn-soft":"btn-primary")+'" data-switch="'+t.id+'">'+(st().currentTenantId===t.id?"当前空间":"进入空间")+'</button>':"")+'</div></div></article>';}).join("")+'</div>'+
    '<div class="card mt-16"><div class="card-head"><h3>租户隔离基线</h3></div><div class="card-body grid g3">'+UI.stat({label:"企业主体",value:"1",unit:"个",delta:"唯一企业根组织"})+UI.stat({label:"启用租户",value:String(ts.filter(function(t){return t.status==="active";}).length),unit:"个",delta:"内部业务单元"})+UI.stat({label:"跨租户默认策略",value:"拒绝",delta:"显式授权并审计"})+'</div></div></div>';
  }
  function detailPage(p){
    var t=App.tenantById(p.id||st().currentTenantId);if(!t)return '<div class="page">'+UI.empty("租户不存在","租户可能已归档。",'<a class="btn" href="'+App.link("tenants/list")+'">返回租户列表</a>')+'</div>';
    var ms=st().members.filter(function(m){return (m.tenantIds||[]).indexOf(t.id)>-1;}),ps=st().projects.filter(function(x){return x.tenantId===t.id;});
    return '<div class="page">'+UI.pageHead({eyebrow:"Tenant · "+esc(t.code),title:esc(t.name),desc:esc(t.description),actions:'<a class="btn" href="'+App.link("tenants/list")+'">返回列表</a><a class="btn btn-primary" href="'+App.link("tenants/policy",{id:t.id})+'">资源策略</a>'})+
    statCards(t,ms.length,ps.length)+'<div class="grid g2 mt-16"><div class="card"><div class="card-head"><h3>空间信息</h3>'+UI.statusBadge(t.status)+'</div><div class="card-body"><div class="kv"><div class="k">租户编码</div><div class="v mono">'+esc(t.code)+'</div><div class="k">组织单元</div><div class="v">'+esc(t.orgUnit)+'</div><div class="k">负责人</div><div class="v">'+esc(t.owner)+'</div><div class="k">创建日期</div><div class="v">'+esc(t.createdAt)+'</div></div></div></div><div class="card"><div class="card-head"><h3>项目归属</h3></div><div class="card-body">'+(ps.map(function(x){return '<div class="list-row"><span class="lr-main"><b>'+esc(x.name)+'</b><small class="lr-sub">'+esc(x.code)+' · '+esc(x.stage)+'</small></span></div>';}).join("")||UI.empty("暂无项目","新建项目时选择此租户空间。"))+'</div></div></div><div class="card mt-16"><div class="card-head"><h3>租户成员</h3><a class="btn btn-xs" href="'+App.link("tenants/members",{id:t.id})+'">成员管理</a></div><div class="card-body">'+ms.map(function(m){return '<div class="list-row">'+UI.avatar(m.name,"sm",m.color)+'<span class="lr-main"><b>'+esc(m.name)+'</b><small class="lr-sub">'+esc(m.role)+' · '+esc(m.dept)+'</small></span>'+UI.statusBadge(m.status)+'</div>';}).join("")+'</div></div></div>';
  }
  function membersPage(p){
    var t=App.tenantById(p.id||st().currentTenantId)||current();if(!t)return '<div class="page">'+UI.empty("没有可用租户","请先选择已加入的租户。")+'</div>';
    var ms=st().members.filter(function(m){return (m.tenantIds||[]).indexOf(t.id)>-1;});
    return '<div class="page">'+UI.pageHead({eyebrow:"Tenant · Members",title:"租户成员",desc:"账号通过租户成员关系获得访问权；移出空间不删除账号和历史资产。",actions:App.hasPerm("tenant:member")?'<button class="btn btn-primary" data-act="add-member">添加成员</button>':""})+'<div class="card"><div class="card-head"><h3>'+esc(t.name)+'</h3><span class="badge b-info">tenant_id: '+esc(t.id)+'</span></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>部门</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>'+ms.map(function(m){return '<tr><td><b>'+esc(m.name)+'</b><small class="t-sub">'+esc(m.email)+'</small></td><td>'+esc(m.dept)+'</td><td>'+esc(m.role)+'</td><td>'+UI.statusBadge(m.status)+'</td><td>'+(App.hasPerm("tenant:member")&&m.id!=="u-owner"?'<button class="btn btn-xs" data-act="remove-member" data-id="'+m.id+'">移出空间</button>':"")+'</td></tr>';}).join("")+'</tbody></table></div></div></div>';
  }
  function policyPage(p){
    var t=App.tenantById(p.id||st().currentTenantId)||current();if(!t)return '<div class="page">'+UI.empty("租户不存在","请选择有效租户。")+'</div>';
    return '<div class="page">'+UI.pageHead({eyebrow:"Tenant · Policy",title:"资源与预算策略",desc:"租户策略只能在企业级策略授权范围内收紧，不能突破企业全局约束。"})+'<div class="grid g2"><div class="card"><div class="card-head"><h3>预算配置</h3><span class="badge b-info">租户独立预算</span></div><div class="card-body"><div class="field"><label>周期预算（元）</label><input class="input" id="budget" type="number" min="0" value="'+Number(t.budget)+'"></div><button class="btn btn-primary mt-16" data-act="save-budget">保存预算策略</button></div></div><div class="card"><div class="card-head"><h3>模型能力白名单</h3><span class="badge b-info">继承企业 Provider</span></div><div class="card-body">'+st().models.map(function(m){return '<label class="checkline mt-8"><input type="checkbox" data-model="'+esc(m.id)+'" '+(t.modelPolicy.indexOf(m.id)>-1?"checked":"")+'> '+esc(m.name)+' · '+esc(m.cap)+'</label>';}).join("")+'<button class="btn btn-primary mt-16" data-act="save-models">保存模型白名单</button><p class="hint mt-8">租户不能新增企业 Provider，也不能读取凭据材料。</p></div></div></div></div>';
  }
  function accessPage(){
    var gs=st().tenantGrants||[];return '<div class="page">'+UI.pageHead({eyebrow:"Enterprise · Delegation",title:"跨租户授权",desc:"跨租户权限默认拒绝；汇总查看不等于项目内容读取或修改。",actions:App.hasPerm("tenant:cross")?'<button class="btn btn-primary" data-act="grant">新增授权</button>':""})+'<div class="notice warn mb-16">'+UI.icon("shield",15)+'<span>所有授权必须记录对象、范围、权限、用途、有效期，并支持撤销。</span></div><div class="card"><div class="table-wrap"><table><thead><tr><th>授权对象</th><th>租户范围</th><th>权限</th><th>用途</th><th>有效期</th><th>状态</th><th></th></tr></thead><tbody>'+gs.map(function(g){return '<tr><td>'+esc(g.subject)+'</td><td>'+esc(g.tenants.join("、"))+'</td><td>'+esc(g.permission)+'</td><td>'+esc(g.purpose)+'</td><td>'+esc(g.expires)+'</td><td>'+UI.statusBadge(g.status)+'</td><td>'+(App.hasPerm("tenant:cross")?'<button class="btn btn-xs" data-act="revoke" data-id="'+g.id+'">撤销</button>':"")+'</td></tr>';}).join("")+'</tbody></table></div></div></div>';
  }
  function createTenant(){
    var body='<div class="form-grid"><div class="field"><label>租户名称 *</label><input class="input" id="tnName"></div><div class="field"><label>租户编码 *</label><input class="input" id="tnCode"></div><div class="field"><label>组织单元</label><input class="input" id="tnOrg"></div><div class="field"><label>负责人</label><select class="select" id="tnOwner">'+st().members.filter(function(m){return m.status==="active";}).map(function(m){return '<option value="'+m.id+'">'+esc(m.name)+'</option>';}).join("")+'</select></div></div>';
    App.modal({title:"创建内部租户",sub:"企业主体："+st().workspace.name,body:body,footer:'<button class="btn" data-close>取消</button><button class="btn btn-primary" id="tnCreate">创建租户</button>',onMount:function(el,close){el.querySelector("#tnCreate").addEventListener("click",function(){var name=el.querySelector("#tnName").value.trim(),code=el.querySelector("#tnCode").value.trim().toUpperCase();if(!name||!code||all().some(function(t){return t.code.toUpperCase()===code;})){App.toast("信息无效","名称和唯一编码均为必填。","warn");return;}var ownerId=el.querySelector("#tnOwner").value,owner=App.memberById(ownerId),id="tn-"+Date.now().toString(36);st().tenants.push({id:id,code:code,name:name,orgUnit:el.querySelector("#tnOrg").value.trim()||name,owner:owner.name,ownerId:ownerId,status:"active",memberIds:[ownerId],projectIds:[],budget:0,spent:0,modelPolicy:[],createdAt:"今天",description:"新建企业内部业务空间"});owner.tenantIds.push(id);var identity=st().identities.filter(function(x){return x.id===ownerId;})[0];if(identity)identity.tenantIds.push(id);App.logAudit("创建内部租户",name,"租户","编码 "+code,"normal",null);close();App.refresh();App.toast("租户已创建",name,"success");});}});
  }
  function mount(root){
    root.addEventListener("click",function(e){var b=e.target.closest("[data-act],[data-switch]");if(!b)return;if(b.hasAttribute("data-switch")){App.setTenant(b.getAttribute("data-switch"));return;}var a=b.getAttribute("data-act"),t=current(),id=b.getAttribute("data-id");
      if(a==="create"){createTenant();return;}
      if(a==="save-budget"){t.budget=Math.max(0,Number(root.querySelector("#budget").value)||0);App.logAudit("更新租户预算",t.name,"租户",String(t.budget),"normal",null);App.refresh();App.toast("预算策略已保存",t.name,"success");}
      if(a==="save-models"){t.modelPolicy=Array.prototype.slice.call(root.querySelectorAll("[data-model]:checked")).map(function(x){return x.getAttribute("data-model");});App.logAudit("更新租户模型白名单",t.name,"租户",t.modelPolicy.join(", "),"normal",null);App.refresh();App.toast("模型白名单已保存","继承企业 Provider","success");}
      if(a==="add-member"){var cs=st().members.filter(function(m){return m.status==="active"&&(m.tenantIds||[]).indexOf(t.id)<0;});var body='<select class="select" id="candidate">'+cs.map(function(m){return '<option value="'+m.id+'">'+esc(m.name)+'</option>';}).join("")+'</select>';App.modal({title:"添加租户成员",body:body,footer:'<button class="btn" data-close>取消</button><button class="btn btn-primary" id="memberAdd">添加</button>',onMount:function(el,close){el.querySelector("#memberAdd").addEventListener("click",function(){var m=App.memberById(el.querySelector("#candidate").value);if(!m)return;m.tenantIds.push(t.id);t.memberIds.push(m.id);var u=st().identities.filter(function(x){return x.id===m.id;})[0];if(u)u.tenantIds.push(t.id);App.logAudit("添加租户成员",m.name,"租户",t.name,"normal",null);close();App.refresh();});}});}
      if(a==="remove-member"){var m=App.memberById(id);App.confirm({title:"移出租户空间",message:"将 "+m.name+" 移出 "+t.name+"？",detail:"不会删除账号或历史资产。",danger:true,okText:"确认移出"}).then(function(ok){if(!ok)return;m.tenantIds=m.tenantIds.filter(function(x){return x!==t.id;});t.memberIds=t.memberIds.filter(function(x){return x!==m.id;});var u=st().identities.filter(function(x){return x.id===m.id;})[0];if(u)u.tenantIds=u.tenantIds.filter(function(x){return x!==t.id;});App.logAudit("移出租户成员",m.name,"租户",t.name,"warning",null);App.refresh();});}
      if(a==="grant"){var body='<div class="form-grid"><div class="field"><label>授权对象</label><select class="select" id="subject">'+st().members.filter(function(m){return m.status==="active";}).map(function(m){return '<option>'+esc(m.name)+'</option>';}).join("")+'</select></div><div class="field"><label>权限</label><select class="select" id="perm"><option>跨租户汇总查看</option><option>跨租户审计查看</option><option>跨租户项目只读</option></select></div><div class="field span2"><label>授权租户范围 *</label><select class="select" id="grantTenants" multiple size="4">'+active().map(function(t){return '<option value="'+t.id+'">'+esc(t.name)+'</option>';}).join("")+'</select><span class="hint">按住 Ctrl / Cmd 可多选；只授予所选租户。</span></div><div class="field span2"><label>授权用途 *</label><input class="input" id="purpose"></div><div class="field"><label>有效期</label><select class="select" id="expiry"><option>7 天</option><option>30 天</option><option>90 天</option></select></div></div>';App.modal({title:"新增跨租户授权",body:body,footer:'<button class="btn" data-close>取消</button><button class="btn btn-primary" id="grantSave">提交授权</button>',onMount:function(el,close){el.querySelector("#grantSave").addEventListener("click",function(){var purpose=el.querySelector("#purpose").value.trim(),selected=Array.prototype.slice.call(el.querySelector("#grantTenants").selectedOptions).map(function(x){return x.value;});if(!purpose||!selected.length){App.toast("授权信息不完整","请明确选择租户范围并填写授权用途。","warn");return;}st().tenantGrants.unshift({id:"TG-"+Date.now(),subject:el.querySelector("#subject").value,tenants:selected.map(function(id){return App.tenantById(id).name;}),tenantIds:selected,permission:el.querySelector("#perm").value,purpose:purpose,expires:el.querySelector("#expiry").value,status:"active"});App.logAudit("创建跨租户授权",el.querySelector("#subject").value,"租户",purpose,"warning",null);close();App.refresh();});}});}
      if(a==="revoke"){var g=st().tenantGrants.filter(function(x){return x.id===id;})[0];if(g){g.status="revoked";App.logAudit("撤销跨租户授权",g.subject,"租户",g.permission,"warning",null);App.refresh();}}
    });
  }
  AppModule.register({group:"tenants",label:"企业空间",icon:"layers",routes:[
    {path:"tenants/list",title:"内部租户空间",icon:"layers",render:listPage,mount:mount},
    {path:"tenants/detail",title:"租户详情",icon:"folder",nav:false,render:detailPage,mount:mount},
    {path:"tenants/members",title:"租户成员",icon:"users",render:membersPage,mount:mount},
    {path:"tenants/policy",title:"资源与预算策略",icon:"sliders",render:policyPage,mount:mount},
    {path:"tenants/access",title:"跨租户授权",icon:"shield",render:accessPage,mount:mount}
  ]});
})();